INSERT OR IGNORE INTO source_attributions("id","name","url","license","license_url","remarks") VALUES ('ukiyora_forms_pdf','Ukiyora Character and Forms Research Index',NULL,'User-supplied research',NULL,'Named forms are unverified editorial candidates.');
DELETE FROM character_search_fts;
INSERT INTO character_search_fts(character_id,name,series_title,aliases)
SELECT c.id,c.name,COALESCE(group_concat(s.name,' '),''),COALESCE((SELECT group_concat(value,' ') FROM json_each(c.aliases_json)),'')
FROM characters c LEFT JOIN appearances a ON a.character_id=c.id
LEFT JOIN series s ON s.id=a.series_id GROUP BY c.id;
